// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CompleteLogin Redirect target registered in authentik; finishes the sign-in
	// (GET /auth/callback)
	CompleteLogin(ctx context.Context, request CompleteLoginRequestObject) (CompleteLoginResponseObject, error)
	// CompleteHomeConnection Redirect target of Home Assistant's sign-in; connects the caller
	// (GET /auth/homeassistant/callback)
	CompleteHomeConnection(ctx context.Context, request CompleteHomeConnectionRequestObject) (CompleteHomeConnectionResponseObject, error)
	// StartLogin Start the sign-in at authentik (browser navigation, not fetch)
	// (GET /auth/login)
	StartLogin(ctx context.Context, request StartLoginRequestObject) (StartLoginResponseObject, error)
	// Logout End the session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetHealth Liveness probe
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetReadiness Readiness probe (checks Postgres and Redis)
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// ListHouseholds Households the current user belongs to
	// (GET /v1/households)
	ListHouseholds(ctx context.Context, request ListHouseholdsRequestObject) (ListHouseholdsResponseObject, error)
	// CreateHousehold Create a household; the caller becomes its owner
	// (POST /v1/households)
	CreateHousehold(ctx context.Context, request CreateHouseholdRequestObject) (CreateHouseholdResponseObject, error)
	// GetHousehold One household with its members (members only)
	// (GET /v1/households/{householdId})
	GetHousehold(ctx context.Context, request GetHouseholdRequestObject) (GetHouseholdResponseObject, error)
	// SuggestRecipes Pick recipes from Mealie that fit a mood (members only)
	// (POST /v1/households/{householdId}/cook/suggestions)
	SuggestRecipes(ctx context.Context, request SuggestRecipesRequestObject) (SuggestRecipesResponseObject, error)
	// GetHome Rooms, scenes, lights and readings from Home Assistant, read live (members only)
	// (GET /v1/households/{householdId}/home)
	GetHome(ctx context.Context, request GetHomeRequestObject) (GetHomeResponseObject, error)
	// DisconnectHome Disconnect your Home Assistant account and revoke its token
	// (DELETE /v1/households/{householdId}/home/connection)
	DisconnectHome(ctx context.Context, request DisconnectHomeRequestObject) (DisconnectHomeResponseObject, error)
	// ConnectHome Start connecting your Home Assistant account
	// (POST /v1/households/{householdId}/home/connection)
	ConnectHome(ctx context.Context, request ConnectHomeRequestObject) (ConnectHomeResponseObject, error)
	// ToggleLight Switch a light on or off
	// (POST /v1/households/{householdId}/home/lights/{lightId}/toggle)
	ToggleLight(ctx context.Context, request ToggleLightRequestObject) (ToggleLightResponseObject, error)
	// ActivateScene Turn a scene on
	// (POST /v1/households/{householdId}/home/scenes/{sceneId})
	ActivateScene(ctx context.Context, request ActivateSceneRequestObject) (ActivateSceneResponseObject, error)
	// CreateInvite Create a one-time invite link code (members only)
	// (POST /v1/households/{householdId}/invites)
	CreateInvite(ctx context.Context, request CreateInviteRequestObject) (CreateInviteResponseObject, error)
	// ListQuestions The household's questions, newest first (members only)
	// (GET /v1/households/{householdId}/questions)
	ListQuestions(ctx context.Context, request ListQuestionsRequestObject) (ListQuestionsResponseObject, error)
	// AskQuestion Ask the household a question
	// (POST /v1/households/{householdId}/questions)
	AskQuestion(ctx context.Context, request AskQuestionRequestObject) (AskQuestionResponseObject, error)
	// GetRecipe A recipe from Mealie with its ingredients and steps (members only)
	// (GET /v1/households/{householdId}/recipes/{slug})
	GetRecipe(ctx context.Context, request GetRecipeRequestObject) (GetRecipeResponseObject, error)
	// AddToShoppingList Put a recipe's missing ingredients on the Mealie shopping list (members only)
	// (POST /v1/households/{householdId}/shopping-list)
	AddToShoppingList(ctx context.Context, request AddToShoppingListRequestObject) (AddToShoppingListResponseObject, error)
	// AcceptInvite Join the household an invite belongs to
	// (POST /v1/invites/{code})
	AcceptInvite(ctx context.Context, request AcceptInviteRequestObject) (AcceptInviteResponseObject, error)
	// GetMe The signed-in user, created on first call
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// AnswerQuestion Write or change your answer; the question opens once every member has answered
	// (PUT /v1/questions/{questionId}/answer)
	AnswerQuestion(ctx context.Context, request AnswerQuestionRequestObject) (AnswerQuestionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

